"""Write AQS-VENT-001 (docs-authority/VENT_CLOSURE.md): the closure rule for vents and stacks, and a check of every
closure against the plant graph. The closures (former open path, required end state, the streams of the normal path
and of the contingency path) are owner decisions of 2026-09-28 and are held in CLOSURES below; every rate, presence and
destination is read from flow_graph/plant_flow_graph.json. Run: python3 docs-authority/_vent_closure.py
"""
import json, os
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R)
DATE = '2026-10-29'
LIFE = ('HAB', 'FARM')   # sectors whose air or water no process vent may reach
# (title, former open path, required end state and why, normal streams, contingency streams)
CLOSURES = [
    ('Process hydrogen', 'roof vent of the dryer', 'Stored in CRYO_H2 and burned by the backup generator and the fuel cell. Hydrogen is never washed with water, which would add a wet explosion hazard; it passes a flame arrestor and the dryer.',
     ['S64', 'S45', 'S49'], ['S24']),
    ('Acid gas and chlorine', 'stack after the alkali scrubber', 'Scrubbed in ALK_SCRUBBER and ACID_POLISH_SCRUB with caustic liquor, which goes to the chlorate unit CRU and on to the leach as oxidant. The cold box never sees acid gas.',
     ['S65', 'S66', 'IA-CRU-01', 'IA-SCRUB-SRC'], []),
    ('Afterburner flue', 'flue of the oil-line afterburner', 'The afterburner still destroys the tar and non-condensable gas; the closure applies to its flue, which goes to the knockout FLUE_KO. Carbon dioxide continues to CRYO_CO2 and the rest of the gas to the nitrogen-oxide scrubber.',
     ['IA-AB-FLUE', 'S67', 'S67B', 'IA-FLUE-EXH', 'S18'], []),
    ('Battery bromine', 'stack of the zinc-bromine battery', 'Absorbed in the bromine regenerator ZNBR2_BR2_REGEN with its own liquor, which returns to the battery as bromide. It is never joined to the chlorate unit.',
     ['S69', 'S69B'], []),
    ('Cryogenic room air', 'exhaust of the cryogenic room air handler', 'The room keeps the mechanical ventilation that NFPA 2 and NFPA 55 require. Condensables are knocked out and returned; only non-condensable gas may leave by the relief route, and only in an upset.',
     ['IA-AHU-POT', 'S70', 'S68', 'IA-HVAC-COND'], ['S56', 'S86']),
    ('Metal-aisle air', 'exhaust of the metal-aisle air handler', 'Scrubbed in MET_SCRUB and returned to the air handler. Fines go to the leach and collected oil to the oil line.',
     ['S62', 'S71', 'IA-MET-AIR-RET', 'S72', 'S72B'], []),
    ('Fuel cell and generator exhaust', 'exhausts of the methanol fuel cell and the backup generator', 'Carbon dioxide from the methanol fuel cell goes to CRYO_CO2; the remaining exhaust and the generator exhaust go to the nitrogen-oxide scrubber NOX_SCRUB, whose water and nitrogen are reused.',
     ['S82', 'IA-FC-EXH', 'S46'], []),
]
g = json.load(open('flow_graph/plant_flow_graph.json')); N = {n['unit_id']: n for n in g['nodes']}
S = {e['stream_id']: e for e in g['edges']}

def rate(sid):
    e = S.get(sid); r = (e or {}).get('rate') or {}; return r.get('value'), r.get('unit')
def live(sid):
    e = S.get(sid); return e is not None and e.get('presence') != 'retired'
def _and(xs):
    xs = list(xs); return ', '.join(xs[:-1]) + ' and ' + xs[-1] if len(xs) > 1 else ''.join(xs)
def fmt(v): return '—' if v is None else f'{v:.4g}'

rows, problems, idle = [], [], []
for title, former, why, normal, cont in CLOSURES:
    for sid in normal + cont:
        if not live(sid):
            problems.append(f'stream {sid} of the {title.lower()} closure is not on the graph'); continue
        e = S[sid]; v, un = rate(sid); kind = 'contingency' if sid in cont else 'normal'
        rows.append((title, sid, e['from_unit_id'], e['to_unit_id'], kind, v, un))
        if kind == 'normal' and not v: idle.append(sid)
        if kind == 'contingency' and v: problems.append(f'contingency stream {sid} carries {fmt(v)} {un} in normal operation')
        if N.get(e['to_unit_id'], {}).get('sector_id') in LIFE: problems.append(f'stream {sid} reaches {e["to_unit_id"]} in a habitation or farm sector')
relief = [u for u, n in N.items() if n.get('presence') == 'present' and (n.get('class') == 'relief' or (n.get('class') == 'boundary' and 'tmospher' in str(n.get('notes') or '')))]
into = [e for e in g['edges'] if e.get('presence') != 'retired' and e['to_unit_id'] in relief and (e.get('rate') or {}).get('unit') != 'kW']
loaded = [e for e in into if (e.get('rate') or {}).get('value')]

md = ['# Vent and stack closure', '', 'Document number: AQS-VENT-001  ', 'Revision: D  ', f'Date: {DATE}  ',
      'Authority: owner decision of 2026-09-28 on the closure of vents; the plant flow graph `flow_graph/plant_flow_graph.json`; the scrubber chemistry AQS-GAS-002; the vent and scrubber list AQS-EQP-VENT-001; the hazard separation register AQS-HSE-001.  ',
      'Generated by `docs-authority/_vent_closure.py` from the plant flow graph; do not edit this page by hand. This is a study, not a construction issue.  ',
      'Licence: CERN-OHL-S-2.0.', '', '| Rev | Description | Date |', '| --- | --- | --- |',
      '| A | First issue: the former outdoor discharges closed by a scrubber with regenerated liquor or by the cryogenic plant. | 2026-09-28 |',
      '| B | Process flow diagram of the closures issued. | 2026-09-28 |',
      '| C | Study estimates of the polish, regenerator, condensate knockout and metal-aisle scrubber duties. | 2026-10-01 |',
      '| D | Generated from the plant graph. Each closure is now checked against the streams on the graph: the normal path must exist, the contingency path must carry no flow, and no process stream may reach the habitation or the farm. Tags no longer on the graph (the demister, the flue capture unit, the acid-gas header, the metal-aisle scrubber regenerator) and the study figures, which now live in AQS-EQP-VENT-001, were removed. | 2026-10-29 |', '',
      '## Purpose and scope', '',
      'The plant does not discharge process gas to outdoors as a normal end state. This page states that rule, lists each former open discharge with the path that now closes it, and checks every closure against the plant graph each time the graph is regenerated. '
      'The chemistry of the scrubbers is in AQS-GAS-002 and their sizes in AQS-EQP-VENT-001.', '',
      '## 1. Terms', '',
      '- Normal path: the streams that carry the vent in normal operation.',
      '- Contingency path: a relief route kept for upsets and life safety, which carries no flow in normal operation.',
      '- Closure: a normal path that ends in a unit that reuses the gas or its absorbed product, not in the atmosphere.', '',
      '## 2. The rule', '',
      'Every former open discharge ends in one of two ways. Toxic, acid and oxidising gases (hydrogen chloride, chlorine, bromine, fume and mist) go to a dedicated scrubber whose liquor is regenerated into a loop already on the plant. Condensable and separable gases (hydrogen, carbon dioxide, boil-off and the non-condensable gas after oxidation) go to the cryogenic plant for condensation and separation. '
      'Relief routes for upsets and for the authority having jurisdiction may remain, but they are not the normal discharge. No process vent shares a duct or a return with the habitation or the farm.', '',
      '## 3. Closures', '', 'Table 3.1 lists the former open discharges and the end state that closes each.', '',
      'Table 3.1. Former open discharges and their closures', '', '| Discharge | Former open path | End state |', '| --- | --- | --- |']
md += [f'| {t} | {f} | {w} |' for t, f, w, _, _ in CLOSURES]
md += ['', '## 4. Check against the graph', '', 'Table 4.1 gives each stream of the closures as the graph carries it.', '',
       'Table 4.1. Streams of the closures', '', '| Discharge | Stream | From | To | Path | Rate | Unit |', '| --- | --- | --- | --- | --- | --- | --- |']
md += [f'| {t} | {s} | {a} | {b} | {k} | {fmt(v)} | {u or "—"} |' for t, s, a, b, k, v, u in rows]
md += ['', ('Every closure holds on the present graph: each named stream exists, each contingency stream carries no flow, and no stream reaches the habitation or the farm.' if not problems
            else 'The check found the following problems, which are open items: ' + '; '.join(problems) + '.'), '']
if idle:
    md += [f'The normal-path streams {_and(idle)} exist but carry no flow at present. They are kept routes, not discharges.', '']
md += [f'The relief units and the atmospheric boundary on the graph are {_and(sorted(relief))}. ' + (f'Of the {len(into)} streams into them, none carries flow in normal operation.' if not loaded
       else 'These streams into them carry flow in normal operation, which the rule does not allow: ' + _and([f"{e['stream_id']} ({fmt(e['rate']['value'])} {e['rate'].get('unit')})" for e in loaded]) + '.'), '']
md += ['## 5. Safety notes', '',
       '1. No duct carries a process atmosphere through the fire barriers into the habitation or the farm.',
       '2. The acid-gas and bromine scrubbers have their fans after the packing and keep their liquors apart (AQS-GAS-002).',
       '3. The afterburner still destroys tar and non-condensable gas; capture of its flue is downstream of the oxidation.',
       '4. The relief routes stay available for upsets and life safety and are labelled as contingency.',
       '5. The maximum allowable quantities of AQS-HSE-001 still apply.',
       '6. The methanol tank breathes through a conservation vent with a flame arrester (NFPA 30); spilled methanol drains to a bonded sump, never to a water tank.', '',
       '## 6. Open items', '',
       '- Confirmation of the residual gas at the outlet of the acid polish scrubber by the authority having jurisdiction.',
       '- The choice of scrubber liquor for the metal aisle, aqueous or oil-side, which AQS-EQP-VENT-001 carries as a study.', '']
open('docs-authority/VENT_CLOSURE.md', 'w').write('\n'.join(md))
print('docs-authority/VENT_CLOSURE.md written')
